#include "PluginEditor.h"
#include "PluginProcessor.h"
namespace bw{
PluginEditor::PluginEditor(PluginProcessor&p):AudioProcessorEditor(p),processor_(p){juce::Component* components[]={&context_,&conversation_,&proposal_,&status_,&analyze_,&stop_,&confirm_,&focus_,&fork_,&approve_,&arm_};for(auto*c:components)addAndMakeVisible(c);analyze_.onClick=[this]{auto s=processor_.uiSnapshot()->scope;processor_.uiActions().enqueue(ui::UiAction::analyze(s.projectId,s.instanceId,s.clipSid.value_or("")));};stop_.onClick=[this]{processor_.uiActions().enqueue(ui::UiAction::stop());};confirm_.onClick=[this]{const auto nonce=processor_.uiSnapshot()->confirmationNonce;if(nonce.empty())processor_.uiActions().enqueue(ui::UiAction::linkConfirmRequest());else processor_.uiActions().enqueue(ui::UiAction::linkConfirmAccept(nonce));};focus_.onClick=[this]{auto s=processor_.uiSnapshot()->scope;processor_.uiActions().enqueue(ui::UiAction::focusSet(s.projectId,s.instanceId,s.clipSid.value_or("")));};fork_.onClick=[this]{auto s=processor_.uiSnapshot()->scope;processor_.uiActions().enqueue(ui::UiAction::forkRequest(s.projectId,s.projectId+"-fork"));};approve_.onClick=[this]{ui::UiAction a{.kind=ui::UiAction::Kind::proposalApprove};processor_.uiActions().enqueue(std::move(a));};arm_.onClick=[this]{ui::UiAction a{.kind=ui::UiAction::Kind::phraseArm};processor_.uiActions().enqueue(std::move(a));};setResizable(true,true);setSize(920,560);startTimerHz(15);timerCallback();}
void PluginEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff15171a));}void PluginEditor::resized(){auto r=getLocalBounds().reduced(12);auto top=r.removeFromTop(48);status_.setBounds(top.removeFromRight(260));context_.setBounds(top);auto actions=r.removeFromBottom(40);for(auto*b:{&analyze_,&stop_,&confirm_,&focus_,&fork_,&approve_,&arm_})b->setBounds(actions.removeFromLeft(112).reduced(3));const bool show=processor_.uiSnapshot()->showProposalDrawer;proposal_.setBounds(r.removeFromRight(show?300:0));conversation_.setBounds(r);proposal_.setVisible(show);}void PluginEditor::timerCallback(){auto s=processor_.uiSnapshot();context_.setText(juce::String("Project: ")+s->scope.projectId+"  Track: "+s->scope.trackHint+"  Instance: "+s->scope.instanceId+(s->scope.confirmed?" [confirmed]":" [hint]"),juce::dontSendNotification);conversation_.setText(juce::String("Conversation / analysis: ")+s->analysis,juce::dontSendNotification);juce::String status(s->connection+" | "+s->session+" | "+s->scheduler);if(s->countdownBeats>0)status<<" "<<juce::String(s->countdownBeats,1)<<" beats";status_.setText(status,juce::dontSendNotification);juce::String proposal;if(s->proposal)proposal<<"Proposal "<<s->proposal->proposalId<<" r"<<s->proposal->revision<<"\n"<<s->proposal->rationale;proposal_.setText(proposal,juce::dontSendNotification);resized();}
}
